import { Settings, importer, midi, model } from '@coderline/alphatab';
import { Midi } from '@tonejs/midi';

import {
  makeExpression,
  pitchAt,
} from 'app/services/MelodiesService/expression';
import type { NoteTechnique } from 'app/services/MelodiesService/types';

import { createImportedTrack } from './convert';
import { normalizeHeader } from './midi';
import {
  PitchEvent,
  combinePitchEvents,
  expressionFromEvents,
} from './pitchAutomation';
import { ImportedSong, MAX_IMPORT_NOTES, MelodyImportError } from './types';

export const parseGuitarProFile = (
  data: Uint8Array,
  filename: string,
): ImportedSong => {
  const settings = new Settings();
  settings.core.useWorkers = false;
  let score: ReturnType<typeof importer.ScoreLoader.loadScoreFromBytes>;
  try {
    score = importer.ScoreLoader.loadScoreFromBytes(data, settings);
  } catch {
    throw new MelodyImportError(
      'Could not read Guitar Pro. Supported formats: .gp3, .gp4, .gp5, .gpx and .gp.',
    );
  }
  const file = new midi.MidiFile();
  const captured = new Map<
    number,
    { pitch: number; start: number; length: number; channel: number }[]
  >();
  const bends = new Map<string, PitchEvent[]>();
  const captureBend = (
    track: number,
    tick: number,
    channel: number,
    key: number | string,
    value: number,
  ) => {
    const id = `${track}:${channel}:${key}`;
    const points = bends.get(id) ?? [];
    points.push({ tick, cents: ((value - 8192) / 8192) * 1600 });
    bends.set(id, points);
  };
  let count = 0;
  // Capture before MIDI channel splitting, so bends and secondary channels
  // do not turn one Guitar Pro part into several selectable tracks.
  class Handler extends midi.AlphaSynthMidiFileHandler {
    private noteBend = false;
    addBend(track: number, tick: number, channel: number, value: number) {
      if (!this.noteBend)
        captureBend(track, tick + this.tickShift, channel, '*', value);
      super.addBend(track, tick, channel, value);
    }
    addNoteBend(
      track: number,
      tick: number,
      channel: number,
      key: number,
      value: number,
    ) {
      captureBend(track, tick + this.tickShift, channel, key, value);
      this.noteBend = true;
      super.addNoteBend(track, tick, channel, key, value);
      this.noteBend = false;
    }
    addNote(
      track: number,
      start: number,
      length: number,
      key: number,
      velocity: number,
      channel: number,
    ) {
      if (++count > MAX_IMPORT_NOTES)
        throw new MelodyImportError(
          'The file has more than 50,000 notes. Choose a file with fewer parts.',
        );
      const notes = captured.get(track) ?? [];
      notes.push({
        pitch: key,
        start: start + this.tickShift,
        length,
        channel,
      });
      captured.set(track, notes);
      super.addNote(track, start, length, key, velocity, channel);
    }
  }
  const handler = new Handler(file, true);
  const generator = new midi.MidiFileGenerator(score, settings, handler);
  generator.generate();
  bends.forEach(points => points.sort((a, b) => a.tick - b.tick));
  const combinedBends = new Map<string, PitchEvent[]>();
  const header = new Midi(file.toBinary()).header;
  const metadata = normalizeHeader(header);
  const title = score.title.trim() || filename.replace(/\.[^.]+$/, '');
  const tracks = score.tracks
    .filter(track => captured.has(track.index))
    .map(track =>
      createImportedTrack({
        ...metadata,
        id: String(track.index),
        title,
        name: track.name.trim() || `Track ${track.index + 1}`,
        author: score.artist.trim() || undefined,
        program: track.playbackInfo.program,
        percussion: track.staves.some(staff => staff.isPercussion),
        notes: captured.get(track.index)!.map(note => {
          const start = header.ticksToSeconds(note.start) * 1000;
          const lookup = generator.tickLookup.findBeat(
            new Set([track.index]),
            note.start - handler.tickShift,
          );
          const source = lookup?.beatLookup.highlightedBeats
            .flatMap(item => item.beat.notes)
            .find(
              n =>
                n.beat.voice.bar.staff.track.index === track.index &&
                n.calculateRealValue(true, true) === note.pitch,
            );
          const chain: model.Note[] = [];
          let linked = source;
          while (linked && !chain.includes(linked)) {
            chain.push(linked);
            linked =
              linked.tieDestination ??
              (linked.slideOutType === model.SlideOutType.Legato
                ? linked.slideTarget
                : null) ??
              undefined;
          }
          const techniques: NoteTechnique[] = [];
          chain.forEach(item => {
            if (item.hasBend) techniques.push('bend');
            if (item.slideInType || item.slideOutType) techniques.push('slide');
            const vibrato = item.vibrato || item.beat.vibrato;
            if (vibrato)
              techniques.push(
                vibrato === model.VibratoType.Wide ? 'wide-vibrato' : 'vibrato',
              );
          });
          const bendKey = `${track.index}:${note.channel}:${note.pitch}`;
          let keyEvents = bends.get(bendKey) ?? [];
          let remapped = false;
          // Legato slides share one sounding source across different written
          // pitches. Destination automation is relative to its own key.
          chain.forEach(item => {
            const key = item.calculateRealValue(true, true);
            if (key === note.pitch || !source) return;
            if (!remapped) {
              keyEvents = keyEvents.slice();
              remapped = true;
            }
            const from =
              note.start +
              item.beat.absolutePlaybackStart -
              source.beat.absolutePlaybackStart;
            (bends.get(`${track.index}:${note.channel}:${key}`) ?? [])
              .filter(
                point =>
                  point.tick >= from && point.tick < note.start + note.length,
              )
              .forEach(point =>
                keyEvents.push({
                  tick: point.tick,
                  cents: point.cents + (key - note.pitch) * 100,
                }),
              );
          });
          if (remapped) keyEvents.sort((a, b) => a.tick - b.tick);
          const events =
            (!remapped && combinedBends.get(bendKey)) ||
            combinePitchEvents(
              keyEvents,
              bends.get(`${track.index}:${note.channel}:*`) ?? [],
            );
          if (!remapped) combinedBends.set(bendKey, events);
          let expression = track.staves.some(staff => staff.isPercussion)
            ? undefined
            : expressionFromEvents(
                events,
                note.start,
                note.start + note.length,
                header,
                techniques,
                techniques.length > 0,
              );
          // alphaTab emits note vibrato in an exclusive branch after bends and
          // slides. Preserve a simultaneous explicit marking as well.
          if (
            source?.vibrato &&
            (source.hasBend || source.slideInType || source.slideOutType)
          ) {
            const wide = source.vibrato === model.VibratoType.Wide;
            const period = wide
              ? settings.player.vibrato.noteWideLength
              : settings.player.vibrato.noteSlightLength;
            const amplitude =
              (wide
                ? settings.player.vibrato.noteWideAmplitude
                : settings.player.vibrato.noteSlightAmplitude) * 50;
            const base = expression?.points ?? [{ position: 0, cents: 0 }];
            const count = Math.max(1, Math.ceil(note.length / 16));
            expression = makeExpression(
              Array.from({ length: count + 1 }, (_, i) => {
                const tick = Math.min(note.length, i * 16);
                const position =
                  (header.ticksToSeconds(note.start + tick) * 1000 - start) /
                  (header.ticksToSeconds(note.start + note.length) * 1000 -
                    start);
                return {
                  position,
                  cents:
                    pitchAt(base, position) +
                    amplitude * Math.sin((2 * Math.PI * tick) / period),
                };
              }),
              techniques,
            );
          }
          return {
            midi: note.pitch,
            start,
            duration:
              header.ticksToSeconds(note.start + note.length) * 1000 - start,
            ...(expression ? { expression } : {}),
          };
        }),
      }),
    );
  if (!tracks.some(track => track.melody.notes.length))
    throw new MelodyImportError(
      'No playable Guitar Pro notes in the C0–B8 range.',
    );
  return { title, format: 'Guitar Pro', tracks };
};
